export function triple(value: number): number {
	return value * 3;
}

/**
 * Doubles a value.
 *
 * Doubling keeps the sign, so negative input stays negative.
 *
 * @param value - The value to double.
 * @returns The doubled value.
 */
export function double(value: number): number {
	debugger;

	return value * 2;
}
